CLASS_ROLES = [('clock', 'Action economy'), ('damage', 'Damage'), ('control', 'Control'), ('shieldmagic', 'Defense'), ('position', 'Mobility'), ('utility', 'Versatility')]
SKILL_ROLES = [('damage', 'Combat'), ('mind', 'Knowledge'), ('talk', 'Social'), ('compass', 'Exploration'), ('position', 'Mobility'), ('shieldmagic', 'Defense')]
DED_ROLES = [('occult', 'Occult casting'), ('damage', 'Combat'), ('utility', 'Utility'), ('team', 'Party role'), ('upgrade', 'Follow-ups'), ('star', 'Flavour')]

# name: (ratings, grade, plan label, evaluation)
F = {}
def f(n, r, g, plan, ev):
    F[n] = (r, g, plan, ev)

# ── Class feats ──
f("Magus's Analysis", '400003', 'S', 'Taken at 1 (Natural Ambition)', "Magus's Analysis combines a Recall Knowledge check with a recharge for a single action, so the action Cyrus would spend recharging also tells the party something useful. The strongest sequence is Spellstrike followed by Analysis on the same target: the earlier hit gives a +1 bonus to the check, Cyrus learns which save or weakness to target next, and he ends the turn charged. Each creature can only be analysed once per day, so against a single boss it is a once-per-fight tool, while against groups it can be used on a different enemy each turn.")
f('Force Fang', '420002', 'A', 'Taken at 2', "Force Fang adds a second conflux spell and therefore a second Focus Point, which is its most important benefit. The spell recharges Spellstrike for one action while dealing guaranteed force damage, so it is a better recharge than the plain action whenever the target is in reach. It has the manipulate trait, so casting it inside an enemy's reach can provoke Reactive Strike. When movement matters more than damage, the Focus Point is better spent on Dimensional Assault.")
f('Expansive Spellstrike', '043003', 'S', 'Planned at 4', "Expansive Spellstrike restores the area of burst, cone and line spells delivered through Spellstrike, turning Cyrus's single-target payloads into tools for groups. With a reach weapon, cones and lines start from any square adjacent to the target rather than from Cyrus, which makes it much easier to aim them away from himself and his allies. It is also the feat that makes Sprinting Spellstrike's line follow his movement at level 12, so in practice it is a prerequisite for the combination he most wants to play.")
f('Running Recharge', '500040', 'A', 'Alternative at 16, or at 8 without the stave', "Running Recharge recharges Spellstrike and lets Cyrus Stride half his Speed or Step for one action, which fixes the magus problem of choosing between moving and recharging on the third action. It is the right pick at 8 if Aspera's stave isn't ready for Fused Staff. At 16 it competes with Arcane Shroud; once Cyrus is regularly quickened, the extra movement matters less, and Arcane Shroud's defensive buff becomes the better use of the slot.")
f("Striker's Scroll", '210002', 'C', 'Not planned', "Striker's Scroll lets Cyrus attach a scroll to Aspera and use it as a Spellstrike payload, including occult scrolls after his dedication. In principle that expands his payload options without spending slots. In practice it occupies Aspera's talisman or spellheart slot, which is better used for the Clay Sphere, and each use consumes a scroll, so it is expensive for what it adds.")
f('Burning Cascade', '020000', 'C', 'Not planned', "Burning Cascade deals Arcane Cascade's extra damage to every enemy within 5 feet when Cyrus enters the stance. Because he fights from 10-foot reach, most enemies are outside the emanation when he enters stance, and each enemy can only be affected once a minute. It offers little to his playstyle.")
f('Distracting Spellstrike', '220000', 'F', 'Unavailable with Aspera', "Distracting Spellstrike requires a free hand and adds a Feint, which uses Deception. Cyrus fights with both hands on Aspera and has not invested in Charisma, so he can't meet the requirement and would gain little if he could.")
f('Reactive Strike', '034200', 'S', 'Planned at 6', "Reactive Strike is the feat that makes a reach weapon work for Cyrus. With 10-foot reach he threatens a large area, and any enemy that moves through it, uses a manipulate action or makes a ranged attack inside it can be struck at full accuracy without affecting his multiple attack penalty. It also combines well with tripping, because a prone enemy that stands up provokes the reaction. A critical hit disrupts a triggering manipulate action, which can stop an enemy spell.")
f('Spell Crash', '330002', 'B', 'Alternative at 6', "Spell Crash spends a prepared spell slot to create a force blast in a 20-foot emanation, 30-foot cone or 60-foot line, dealing damage based on the slot's rank. Because Aspera has the trip trait, every creature that fails its save also falls prone. With one or two fights a day Cyrus often has spare slots, which makes this more appealing than it would be in a long dungeon. It still uses his spell DC, and Reactive Strike provides more consistent value every turn.")
f("Conjurer's Countermeasure", '200300', 'B', 'Alternative at 6', "Conjurer's Countermeasure is a conflux spell that grants resistance 5 to spell damage, stacking with Arcane Cascade's resistance. As a conflux spell it also recharges Spellstrike when cast and adds a Focus Point. It is a strong choice for campaigns heavy with enemy spellcasters, but Reactive Strike is the better general-purpose feat at this level.")
f('Knowledge is Power', '000101', 'C', 'Not planned', "Knowledge is Power grants small bonuses after a critical success on Recall Knowledge. Critical successes are too unreliable to build around and the bonuses are minor, so it is a poor use of a class feat.")
f('Spell Retaliation', '300000', 'C', 'Not planned', "Spell Retaliation recharges Spellstrike as a free action when Cyrus succeeds at a save against an enemy spell or an enemy spell attack misses him. It only helps in fights against spellcasters and depends on the enemy acting first, so it is too situational for a class feat.")
f('Fused Staff', '200005', 'A', 'Planned at 8 if the stave is ready', "Fused Staff merges a magical staff into Aspera, so Cyrus can cast the staff's spells while holding his weapon in both hands, and the fused item uses the higher of the two items' fundamental runes. Its value is entirely the staff's spell list, which is why it is planned for the level at which Aspera's bespoke stave exists. With one or two fights a day, the staff's daily charges are spread across very few encounters, which makes each charge more valuable.")
f('Standby Spell', '000004', 'B', 'Alternative at 8', "Standby Spell lets Cyrus cast one chosen Spellstrike payload from any slot of high enough rank without preparing it. It helps if he often finds the right payload unprepared, but with careful daily preparation and few fights a day that problem is less common.")
f('Runic Impression', '330003', 'B', 'Alternative at 8', "Runic Impression is a conflux spell that gives Aspera a chosen property rune, such as flaming, frost or ghost touch, for a short time. It also recharges Spellstrike and adds a Focus Point. It is a flexible answer to resistances and incorporeal enemies, but it competes with Fused Staff at this level.")
f('Spell Swipe', '320000', 'C', 'Not planned', "Spell Swipe makes a Spellstrike against two adjacent creatures within reach for three actions. It leaves no action for moving or recharging, and the targets must be adjacent to each other, so it rarely fits Cyrus's turn.")
f('Capture Magic', '100200', 'C', 'Not planned', "Capture Magic lets Cyrus enter or boost Arcane Cascade as a reaction after resisting an enemy spell. It competes with Reactive Strike for his reaction and only triggers against spellcasters.")
f('Dimensional Disappearance', '320450', 'S', 'Planned at 10', "Dimensional Disappearance makes Cyrus invisible after every Dimensional Assault. He can skip the Strike to stay hidden and reposition safely, or make the Strike against an enemy that can't see him, which leaves it off-guard and turns on Laughing Shadow's increased damage. That makes it both his best escape and his best opening attack, and it reduces his need for Invisibility spell slots. It is central to the elusive, teleporting style Cyrus is built around.")
f('Cascading Ray', '300001', 'B', 'Alternative at 10 or 16', "Cascading Ray lets Cyrus follow a successful Spellstrike that dealt energy damage with a one-action ray against a second enemy within 120 feet. It uses his spell attack at the same multiple attack penalty as the Strike, so it misses more often than Aspera would, but it is a reasonable use of a spare third action.")
f('Rapid Recharge', '300000', 'B', 'Alternative', "Rapid Recharge recharges Spellstrike as a free action once per day. With one or two fights a day that is close to once per fight, which makes it better at this table than usual. It still offers less than Dimensional Disappearance at level 10.")
f('Sprinting Spellstrike', '440060', 'S', 'Planned at 12', "Sprinting Spellstrike is a core part of Cyrus's design, both as the thematic and exciting option the player wants and for what it adds to his mobility and damage. He moves in a straight line up to the length of a line spell, passing through enemies without triggering reactions, and then makes his Spellstrike. With Expansive Spellstrike, the spell's line follows his movement, so every enemy along the path is hit by the spell. It combines well with Lightning Bolt and Blazing Fissure, and with Living Thunderbolt, whose fly Speed Sprinting can use and which damages every creature he passes through.")
f('Conflux Focus', '300002', 'C', 'Not planned', "Conflux Focus refills Cyrus's whole focus pool whenever he Refocuses. At this table, with one or two fights a day and time to rest between them, ordinary Refocus already restores most or all of the pool before the next fight. It would only matter on long dungeon days with several fights in a row.")
f('Overwhelming Spellstrike', '300000', 'C', 'Not planned', "Overwhelming Spellstrike ignores energy resistance equal to Cyrus's level for one Spellstrike. Arcane Cascade's damage-type switch and a varied set of payloads usually solve the same problem.")
f('Magic Sense (Magus)', '000003', 'C', 'Not planned', "Magic Sense gives Cyrus a permanent 1st-rank Detect Magic in his field of vision. Detect Magic is already a cantrip and the party's casters have it, so a class feat is too high a price.")
f('Hasted Assault', '500030', 'A', 'Planned at 14', "Hasted Assault is a conflux spell that makes Cyrus quickened for a minute, with the extra action usable for Stride or Strike, and it recharges Spellstrike when cast. Cast in the first round, it gives him an extra action every turn of the fight, close to a permanent Haste on himself. It doesn't stack with Haste, which frees the party's Haste for Mira or Cassius. It also adds a third Focus Point.")
f('Arcane Shroud', '303433', 'A', 'Planned at 16', "Arcane Shroud turns every entry into Arcane Cascade into a short buff: Cyrus picks one of his three chosen spells each time and keeps it until the end of his next turn. By 16 he is often quickened from Haste, Hasted Assault or an ally, which covers the movement that Running Recharge was meant to provide and leaves a normal action free to re-enter the stance. Invisibility is the strongest pick: re-entered as the last action of a turn, it forces a DC 11 flat check on every attack against him until his next hostile action, and the Strike that ends it is made while he is hidden, so the target is off-guard and Laughing Shadow applies. Fleet Step and See the Unseen are the other useful choices, and False Vitality gives temporary Hit Points that can be refreshed for one action. Two limits matter: he gets one of the three spells per entry, not all three, and stances can only be entered in encounter mode, so it gives no out-of-combat invisibility for scouting. Re-entering is also limited to once per round by the stance trait.")
f('Dispelling Spellstrike', '020003', 'C', 'Not planned', "Dispelling Spellstrike adds a counteract attempt to a three-action Spellstrike. A Dispel Magic scroll or the party's casters handle buffs and wards more cheaply.")
f('Resounding Cascade', '210200', 'B', 'Alternative at 16', "Resounding Cascade extends Arcane Cascade's base extra damage and resistance to allies within 5 feet of Cyrus. Because he fights from 10-foot reach, his allies are often not within 5 feet, which limits its value for him.")

# ── Skill and general feats ──
f('Fleet', '300050', 'S', 'Taken at 1 (Versatile Human)', "Fleet adds 5 feet to Cyrus's Speed, and almost everything this build does scales with Speed. Dimensional Assault teleports up to half his Speed before level 9 and his full Speed after, so Fleet extends every teleport; it also extends every Stride to a flanking square and every approach before a Sprinting Spellstrike. It stacks with Laughing Shadow's bonus and with boots, and it costs nothing to use. For a reach skirmisher whose turns depend on reaching the right square, no other general feat adds as much to every fight.")
f('Canny Acumen', '302302', 'A', 'Taken at 1 (background)', "Expert Perception from level 1 to 8 is eight levels ahead of the class. Perception is his initiative, so in the campaign's hard fights it decides whether Cyrus trips or debuffs the key enemy before it acts. It is also the roll for spotting ambushes and hidden creatures in exploration, and for Sense Motive in the social scenes that fill most sessions. The class catches up at 9, but the feat then takes him to master at 17, so it keeps paying off at both ends of the campaign.")
f('Additional Lore', '350000', 'S', 'Taken (Academia from the campaign, Warfare at 2)', "Additional Lore raises its chosen Lore to expert at 3, master at 7 and legendary at 15 without spending skill increases. That is how Cyrus keeps two strong Lores while still raising Athletics and Arcana. Warfare Lore reaching master at 7 is what unlocks Improvise Strategy, so this feat supports his combat plan as well as his scholarly role.")
f('Toughness', '100004', 'A', 'Taken at 3', "Toughness adds Hit Points equal to Cyrus's level and lowers the DC of recovery checks. He fights from inside the enemy line, ends turns next to the target and spends actions on Spellstrike rather than defence, so the hard fights are where he is most likely to drop. Extra Hit Points every fight, plus a better chance of stabilising when he does go down, make it one of the most reliable general feats for him. It does nothing else, which is the only reason it isn't higher.")
f('Incredible Initiative', '400000', 'A', 'Planned at 5 (General Training)', "Incredible Initiative gives +2 to initiative rolls. Acting before enemies lets Cyrus trip or debuff a key enemy before the rest of the party acts, and reposition before the enemy can surround the party.")
f("Kreighton's Cognitive Crossover", '150100', 'A', 'Planned at 4', "Kreighton's Cognitive Crossover lets Cyrus retry a failed Recall Knowledge check with a second chosen skill as a reaction. Pairing Arcana with Academia Lore or Society means far fewer blank results when he identifies an enemy, an artefact or a historical clue. It also backs up Magus's Analysis in combat, though the reaction competes with Reactive Strike there. It is a legacy feat that was not reprinted, so it remains available.")
f('Magical Shorthand', '030200', 'A', 'Planned at 6', "Magical Shorthand turns every successful Learn a Spell check into a critical success, which halves the cost, and makes learning any spell take 10 minutes regardless of rank. Gold is the tightest resource in this build, with runes, Aspera's stave and invested items all competing for it, so halving the cost of every spell Cyrus adds to his spellbook is a meaningful saving across the campaign. The 10-minute learning time matters as much: downtime may be rare, and this lets him copy a scroll or a captured spellbook during a short rest. The downtime option to learn spells instead of earning income is a bonus when downtime does come.")
f('Improvise Strategy', '500000', 'S', 'Planned at 7', "Improvise Strategy costs one action and uses Warfare Lore against a creature's Perception DC, so it leaves Cyrus's first attack free for the Strike or Trip that follows. On a success the target is clumsy, dazzled, off-guard or stupefied until the end of his next turn. Off-guard turns on Laughing Shadow's increased damage, and clumsy makes the following Trip easier. It is the opening move of his signature turn: Improvise Strategy, then Trip, then Dimensional Assault.")
f('Battle Planner', '200000', 'C', 'Not planned', "Battle Planner lets Cyrus spend a minute planning and use a Warfare Lore roll as his initiative if the plan still holds. It only works when the party has time to scout, and Incredible Initiative improves his initiative more reliably.")
f('Unmistakable Lore', '050200', 'A', 'Planned at 8', "Unmistakable Lore removes critical failures on Recall Knowledge with any Lore Cyrus is trained in, and gives extra information on critical successes once he is a master. Critical failures on Recall Knowledge give false information, which is worse than nothing when the party acts on it. As the party's scholar, with several Lores from Additional Lore and Aspera's gifts, he rolls these checks often in both investigation and combat, so the protection is used most sessions.")
f('Courtly Graces', '005200', 'A', 'Planned at 10', "Courtly Graces lets Cyrus use Society to make an impression on nobles and to impersonate them. In a campaign driven by roleplay, with the party tied into Cormyrean noble houses through Cassius, it gives him a dependable social tool built on his strongest Intelligence skill rather than Charisma. It also matches his background as a scholar who understands courtly etiquette. It has no use in combat, which matters little for a skill feat.")
f('Leverage Connections', '004200', 'B', 'Alternative at 12', "Leverage Connections lets Cyrus call in favours from contacts once a week. In a roleplay-heavy campaign with recurring noble and academic contacts it is a real source of information, access and introductions. Its value depends on how often the party returns to places where he has a network.")
f('Titan Wrestler', '400000', 'A', 'Planned at 12', "Titan Wrestler lets Cyrus Trip, Grapple, Shove, Reposition and Disarm creatures two sizes larger than him, or three at legendary Athletics. From level 12 many bosses are Huge or larger, and without this feat his main setup action stops working against them, so it keeps his tripping style effective late in the campaign.")
f('Quick Jump', '000020', 'C', 'Alternative', "Quick Jump turns High Jump and Long Jump into single actions without a run-up. It helps on vertical maps, but Dimensional Assault and Time Jump cover most of the same movement.")
f('Bon Mot', '310000', 'C', 'Alternative', "Bon Mot imposes a penalty to Will saves and Perception for one action, which supports the party's Will-targeting casters. It uses Diplomacy, and Cyrus's Charisma is low, so it is less reliable for him than Improvise Strategy.")
f('Unified Theory', '050300', 'A', 'Planned at 15', "Unified Theory lets legendary Arcana stand in for Nature, Occultism and Religion on checks about magic. That makes Cyrus the party's answer to every magical item, effect, ward or creature, using his best skill. In a campaign with a lot of investigation, it saves the party from depending on whoever happens to have the matching skill.")
f('Trick Magic Item', '000300', 'C', 'Not planned', "Trick Magic Item lets Cyrus try to activate items from traditions he can't cast. The Witch or Psychic dedication gives him occult casting directly, which covers most items he would want.")
f('Prescient Planner', '000300', 'C', 'Not planned', "Prescient Planner lets Cyrus retrieve a common item he didn't pack, for its price. It needs a second feat to cover consumables, and a well-chosen kit covers most of the same needs.")
f('Prescient Consumable', '000300', 'C', 'Not planned', "Prescient Consumable extends Prescient Planner to consumables. Two feats for flexible shopping is a poor trade compared with planning the kit.")
f('Biographical Eye', '003100', 'B', 'Not planned', "Biographical Eye lets Cyrus infer a stranger's background after a minute of observation. In a campaign with a lot of intrigue it gives useful leverage before a conversation starts, but it needs a minute and a willing GM to pay off, so it is a good free pick rather than a priority.")
f("Axuma's Awakening", '200300', 'B', 'Planned at 11 (reflavoured)', "Axuma's Awakening gives two arcane cantrips at will and one rank 1 and one rank 2 spell once a day, all as innate spells keyed to Charisma. Cyrus's Charisma is low, so the right picks are spells that need no attack roll or save. Sure Strike at rank 1 makes one Spellstrike a fortune roll; Hidebound or Warping Pull at rank 2 are reactions that protect an ally from a hit; Lucky Number is the alternative if he would rather keep a once-a-day reroll for himself. For the cantrips, Shield, Message and Telekinetic Hand free his prepared cantrips for damage. It is a good general feat at 11 because it adds a fortune effect and a reaction without costing slots, but none of it changes his turn the way a class feat does.")
f('Assurance', '200000', 'C', 'Not planned', "Assurance gives a fixed result on Athletics checks. Cyrus's Athletics bonus is high, so rolling usually gives a better result.")
f('Kip Up', '000030', 'C', 'Not planned', "Kip Up lets Cyrus stand without provoking reactions. It helps against enemies that trip, but it is a narrow defensive feat.")
f('Combat Climber', '000020', 'C', 'Not planned', "Combat Climber removes the off-guard condition while climbing. Gecko Grip becomes a studious spell at 7 and covers most climbing needs.")
f('Powerful Leap', '000020', 'C', 'Not planned', "Powerful Leap increases jump distance. Time Jump and Fly provide much more movement.")

# ── Ancestry ──
f('Natural Ambition', '400000', 'S', 'Taken at 1', "Natural Ambition gave Cyrus Magus's Analysis at level 1, a feat he uses in every fight.")
f('General Training', '300000', 'A', 'Planned at 5', "General Training grants a level-1 general feat. Incredible Initiative is the planned choice, improving Cyrus's chance of acting before the enemy.")
f('Clever Improviser', '002200', 'B', 'Alternative at 13', "Clever Improviser lets Cyrus attempt actions that normally need training and improves his untrained checks. It suits a generalist scholar who is often asked to try unfamiliar tasks.")
f('Multitalented', '300003', 'A', 'Planned at 9', "Multitalented grants a multiclass dedication feat without its usual requirements. It is how Cyrus gains occult casting, which fills the party's missing tradition.")
f('Advanced General Training', '300000', 'B', 'Alternative at 13', "Advanced General Training grants a general feat of level 7 or lower, such as a second skill feat or Prescient Consumable.")

# ── Dedications at 9 ──
f('Witch Dedication', '514534', 'S', 'Recommended at 9', "Witch Dedication gives Cyrus the occult Cast a Spell activity, which lets him use occult scrolls, wands and Aspera's stave, including Synesthesia. Under the remastered rules he uses his existing spell attack and spell DC rather than a weaker trained value, so his occult items are as effective as his arcane spells. It also gives him a familiar with two occult cantrips, such as Guidance and Read the Air, and the familiar's own abilities. That makes him the party's occult caster without spending any further feats.")
f('Psychic Dedication', '533523', 'A', 'Alternative at 9', "Psychic Dedication grants the same occult casting access as the Witch dedication, plus one psi cantrip from a chosen conscious mind. Some psi cantrips are attack spells that work as Spellstrike payloads. It has no familiar, so it trades utility for combat value. Choose it if the extra combat cantrip matters more than a familiar.")
f('Rogue Dedication', '030202', 'C', 'Not recommended', "Rogue Dedication requires Dexterity +2, which Cyrus doesn't plan to have. Its Surprise Attack and extra skill feat don't address the party's needs.")
f('Exemplar Dedication', '040113', 'B', 'Flavour option', "Exemplar Dedication grants an ikon with its own empowered effects, which suits a character whose weapon is a growing relic. It adds no occult casting, so the party would still lack an occult caster.")
f('Commander Dedication', '030445', 'A', 'Flavour option', "Commander Dedication grants Intelligence-based tactics that move or empower allies, and its Warfare Lore theme fits Cyrus closely. It is a strong team option, but it doesn't give occult casting, so the party would still lack an occult caster.")


# ── plan as of level 4: campaign bonus feats, the level-20 build, and evaluations that name no party member ──
def _relabel(n, plan, old=None, new=None, grade=None):
    r, g, _p, ev = F[n]
    if old is not None:
        assert old in ev, n
        ev = ev.replace(old, new)
    F[n] = (r, grade or g, plan, ev)

_relabel('Expansive Spellstrike', 'Taken at 4')
_relabel('Fused Staff', 'Planned at 8')
_relabel('Witch Dedication', 'Planned at 9')
_relabel('Unified Theory', 'Planned at 16')
_relabel('Leverage Connections', 'Alternative at 14')
_relabel('Clever Improviser', 'Alternative at 13')
_relabel('Quick Jump', 'Planned at 14', "but Dimensional Assault and Time Jump cover most of the same movement.",
         "but Dimensional Assault and Time Jump cover most of the same movement. It is the base for Cloud Jump at 18, which is where the pair becomes worth using.")
_relabel('Arcane Shroud', 'Planned at 16', "which covers the movement that Running Recharge was meant to provide and leaves a normal action free to re-enter the stance.",
         "which covers his movement and leaves a normal action free to re-enter the stance.")
_relabel('Hasted Assault', 'Planned at 14', "which frees the party's Haste for Mira or Cassius. It also adds a third Focus Point.",
         "which frees the party's Haste for another melee ally. It also adds a third Focus Point. From level 20 Supreme Spellstrike makes him permanently quickened, so Hasted Assault then adds only Stride as a use for the extra action, alongside its Focus Point and its recharge.")
f('Running Recharge', '500040', 'A', 'Taken at 4 (campaign bonus class feat)', "Running Recharge recharges Spellstrike and lets Cyrus Stride half his Speed or Step for one action, which fixes the magus problem of choosing between moving and recharging on the third action. A turn can be Running Recharge to a flanking square followed by Spellstrike, without spending a Focus Point. It is the recharge to use when Magus's Analysis has already been spent on the target and he needs to move. When the target is already in reach and flanked, Force Fang adds damage for the same action.")
f('Courtly Graces', '005200', 'A', 'Planned at 10', "Courtly Graces lets Cyrus use Society to make an impression on nobles and to impersonate them. It gives him a dependable social tool in any scene set among nobility, built on an Intelligence skill rather than Charisma. It also matches his background as a scholar who understands courtly etiquette. It has no use in combat, which matters little for a skill feat.")
f('Prescient Planner', '000300', 'C', 'Taken at 3 (campaign bonus general feat)', "Prescient Planner lets Cyrus spend a minute to produce a common piece of adventuring gear he had not declared buying, for its price, once between each chance to shop. The item's level can be no higher than half his own, and it cannot be a weapon, armour, an alchemical item or a magic item. On its own it only covers mundane gear, such as rope, tools or a ladder. Cyrus takes it with the campaign's bonus general feat because it is the prerequisite for Prescient Consumable at 13.")
f('Prescient Consumable', '000400', 'B', 'Planned at 13 (Advanced General Training)', "Prescient Consumable lets Prescient Planner produce a common consumable in place of adventuring gear: a scroll, potion, talisman or similar item of a level no higher than half his own, for its price. At 13 that reaches level-6 items, such as a rank-3 scroll, and at 20 level-10 items, such as a rank-5 scroll. For a prepared caster with two slots of each rank, one unplanned scroll is a way to have a spell he did not prepare, including occult scrolls after the dedication. It takes a minute, so it is used before a fight or during exploration, and it works once between each chance to shop. It costs two feats in total, which is why it is graded below the feats that work in every fight.")
f('Advanced General Training', '300000', 'B', 'Planned at 13', "Advanced General Training grants a general feat of level 7 or lower. Cyrus uses it for Prescient Consumable, which needs Prescient Planner from level 3.")
f('Stolen Spell', '230003', 'B', 'Planned at 18', "Stolen Spell triggers as a free action when Cyrus critically succeeds at a save against an enemy's spell, or an enemy critically fails a spell attack roll against him. He can then cast that spell once before the end of his next turn at no cost, even if it is not an arcane spell or is of a higher rank than he can cast, and if he delivers it through Spellstrike to the creature that cast it, that creature is off-guard against the Strike. A free high-rank payload against an off-guard target is one of the strongest turns he can have. It depends on facing enemy spellcasters and on a critical success, so it does nothing in most fights. Versatile Spellstrike is the alternative at this level: it holds one slot open and fills it from his spellbook, two ranks lower, at the moment of a Spellstrike, which works in every fight and suits a spellbook built to cover every save.")
f('Supreme Spellstrike', '640000', 'S', 'Planned at 20', "Supreme Spellstrike makes Cyrus permanently quickened, with the extra action limited to a Strike or to recharging Spellstrike. A free recharge every turn means a Spellstrike every round, with the third action left for moving, Magus's Analysis, a conflux spell or Arcane Cascade. Aspera's planned grand gift at 17 removes the limit on what the extra action can be used for. Quickened from several sources still gives one extra action, so from this level Haste and Hasted Assault only add more ways to use it.")
f('Cloud Jump', '100240', 'B', 'Planned at 18', "Cloud Jump triples the distance of a Long Jump and lets a High Jump use Long Jump distances, and extra actions extend a jump beyond his Speed. With Quick Jump, one action carries Cyrus up to his full Speed across a gap, a hazard or difficult terrain on a check he passes easily at legendary Athletics, or straight up to a ledge. It costs no spell slot or Focus Point. Fly and Dimensional Assault cover much of the same ground, so its value is on maps with height and broken terrain, and it needs Quick Jump to be worth an action in a fight.")
f('Legendary Professional', '003100', 'C', 'Planned at 20', "Legendary Professional makes Cyrus famous for one of his Lores. People with any knowledge of Society have heard of him and usually start one step friendlier, and he finds higher-level work when he Earns Income with that Lore. It has no effect in a fight. It fits a level-20 scholar and tactician, and by 20 the skill feats that matter in combat are already taken.")
f('Heroic Presence', '300003', 'B', 'Planned at 17', "Once a day, for one action, Heroic Presence gives up to 10 willing creatures within 30 feet the effects of a 6th-rank Zealous Conviction: 12 temporary Hit Points and a +2 status bonus to Will saves against mental effects for 10 minutes. It is a party-wide effect for a single action, from a spell that is not on the arcane list. The temporary Hit Points are small at level 17, so most of its value is the Will bonus in fights with fear, control or other mental effects.")
f('Sanguine Tenacity', '000003', 'B', 'Planned at 19', "Sanguine Tenacity treats enfeebled and drained as 1 lower when working out their penalties and the Hit Points that drained removes. It also gives resistance 5 to persistent bleed damage and makes that damage easier to end. Enfeebled lowers attack rolls, damage and Athletics checks, so ignoring enfeebled 1 protects both Spellstrike and Trip. It needs Constitution +4, which the plan reaches at 15. It only matters against enemies that inflict those conditions.")
_relabel("Kreighton's Cognitive Crossover", 'Taken at 4', " It is a legacy feat that was not reprinted, so it remains available.", "")
_relabel('Witch Dedication', 'Planned at 9', "Under the remastered rules he uses his existing spell attack and spell DC rather than a weaker trained value, so his occult items are as effective as his arcane spells.",
         "He uses his existing spell attack and spell DC for them, so his occult items are as effective as his arcane spells.")
